import fs from 'node:fs'
export async function execute(args = {}) {
  if (!args.a || !args.b) throw new Error('a and b required')
  const a = fs.readFileSync(args.a, 'utf8').trim().split(/\r?\n/)
  const b = fs.readFileSync(args.b, 'utf8').trim().split(/\r?\n/)
  return { lines: a.map((x, i) => x + (b[i] || '')) }
}

import test from 'node:test'
import assert from 'node:assert'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { execute } from '../lib/impl.js'
test('join', async () => {
  const d = fs.mkdtempSync(path.join(os.tmpdir(), 'bench-join-'))
  const a = path.join(d, 'a.txt'); const b = path.join(d, 'b.txt')
  fs.writeFileSync(a, 'a\nb\n'); fs.writeFileSync(b, '1\n2\n')
  assert.deepEqual((await execute({ a, b })).lines, ['a1', 'b2'])
})
